import random
import string
from typing import List

# This generator produces valid null-terminated C strings tailored to exercise
# the fsearch_* string utilities. It focuses on ASCII (valid UTF-8 subset) but
# can include paths, filenames, wildcard patterns, regex metachars, intervals, and
# mixed-case content. No interior NULs are inserted; a single trailing NUL is added.

ASCII_PRINTABLE = ''.join(chr(i) for i in range(0x20, 0x7f))
ASCII_ALNUM = string.ascii_letters + string.digits
ASCII_PUNCT = ''.join(ch for ch in ASCII_PRINTABLE if ch not in ASCII_ALNUM and ch != '\\')

# Building blocks for interesting cases
PATH_SEPS = ['/']
DRIVE_LETTERS = [chr(c) for c in range(ord('A'), ord('Z') + 1)]
WILDCARDS = ['*', '?']
REGEX_META = ['.', '+', '(', ')', '[', ']', '{', '}', '^', '$', '|']
COMMON_EXTS = ['txt', 'c', 'cpp', 'h', 'hpp', 'md', 'json', 'xml', 'tar.gz', 'bashrc', 'config', '']


def _maybe(prob: float) -> bool:
    return random.random() < prob


def _rand_len(lo: int, hi: int) -> int:
    return random.randint(lo, hi)


def _rand_ascii(n: int) -> str:
    # Mix letters, digits, and punctuation, but avoid interior NULs
    pool = ASCII_PRINTABLE
    return ''.join(random.choice(pool) for _ in range(n))


def _rand_name() -> str:
    # Filename-like token
    base_len = _rand_len(1, 12)
    base = ''.join(random.choice(string.ascii_letters + string.digits + '_-') for _ in range(base_len))
    if _maybe(0.7):
        ext = random.choice(COMMON_EXTS)
        if ext:
            # allow multi-dot extensions like tar.gz
            return base + '.' + ext
    return base


def _rand_path(depth_min: int = 1, depth_max: int = 4) -> str:
    parts: List[str] = []
    # Optional drive prefix (Windows-like) or leading slash (Unix)
    if _maybe(0.25):
        parts.append(random.choice(DRIVE_LETTERS) + ':' + PATH_SEPS[0])
    elif _maybe(0.5):
        parts.append(PATH_SEPS[0])
    depth = _rand_len(depth_min, depth_max)
    for i in range(depth):
        # Mix hidden files, normal names, and dotted names
        if _maybe(0.15):
            # Hidden file like .bashrc
            parts.append('.' + _rand_name())
        else:
            parts.append(_rand_name())
        # add separator between parts except maybe last if root-like first chunk already ended with sep
        if i < depth - 1:
            parts.append(PATH_SEPS[0])
    return ''.join(parts)


def _inject_case_mix(s: str) -> str:
    # Ensure presence/absence of uppercase for has_upper and UTF-8 variant
    if any(c.isalpha() for c in s):
        chars = list(s)
        if _maybe(0.6):
            # force at least one uppercase
            idxs = [i for i, c in enumerate(chars) if c.isalpha()]
            if idxs:
                i = random.choice(idxs)
                chars[i] = chars[i].upper()
        else:
            # optionally make all lower
            chars = [c.lower() if c.isalpha() else c for c in chars]
        return ''.join(chars)
    else:
        # possibly add an upper if none present
        if _maybe(0.5):
            s += random.choice(string.ascii_uppercase)
        return s


def _inject_wildcards(s: str) -> str:
    # Insert wildcard characters for has_wildcards and conversion
    chars = list(s)
    if not chars:
        return '*'
    if _maybe(0.5):
        # Put a wildcard near the start or middle
        pos = min(len(chars) - 1, max(0, len(chars) // 2))
        chars[pos] = random.choice(WILDCARDS)
    if _maybe(0.3) and len(chars) > 1:
        pos = random.randrange(0, len(chars))
        chars[pos] = random.choice(WILDCARDS)
    return ''.join(chars)


def _sprinkle_regex_meta(s: str) -> str:
    if not s:
        return '.[a-z]*'
    chars = list(s)
    # ensure some regex metachars appear to exercise escaping logic
    if len(chars) > 2:
        chars[0] = '.'
        chars[1] = '['
        # close the bracket later if possible
        insert_close_at = len(chars) - 1
        chars[insert_close_at] = ']'
    if _maybe(0.4):
        # Add a plus or braces somewhere
        pos = random.randrange(0, len(chars))
        chars[pos] = random.choice(['+', '{', '}', '^', '$', '|'])
    return ''.join(chars)


def _maybe_interval_prefix(s: str) -> str:
    # For starts_with_interval: optionally force ".." or "-" at start
    if not s:
        s = _rand_ascii(_rand_len(1, 8))
    if _maybe(0.33):
        return '..' + s
    if _maybe(0.33):
        return '-' + s
    return s


def _produce_variant() -> str:
    # Choose among several families to cover different functions
    choice = random.random()
    if choice < 0.12:
        # Empty string
        return ''
    elif choice < 0.28:
        # Simple ASCII word, mixed case
        s = ''.join(random.choice(string.ascii_letters) for _ in range(_rand_len(1, 24)))
        return _inject_case_mix(s)
    elif choice < 0.48:
        # Path-like with extensions and hidden files
        s = _rand_path()
        return _inject_case_mix(s)
    elif choice < 0.68:
        # Filename with multiple dots and common tricky cases
        parts = [
            _rand_name(),
            random.choice(['.', '..', '...', '.', '.']),
            _rand_name(),
        ]
        s = ''.join(parts)
        return _inject_case_mix(s)
    elif choice < 0.82:
        # Wildcard-heavy pattern
        s = _rand_name()
        s = _inject_wildcards(s)
        s = _sprinkle_regex_meta(s)
        s = _maybe_interval_prefix(s)
        return s
    else:
        # General ASCII string with punctuation, ensure ASCII-only for UTF-8 checks
        s = _rand_ascii(_rand_len(1, 64))
        s = _inject_case_mix(s)
        if _maybe(0.5):
            s = _inject_wildcards(s)
        if _maybe(0.5):
            s = _sprinkle_regex_meta(s)
        s = _maybe_interval_prefix(s)
        return s


def _ensure_ascii_no_nul(s: str) -> str:
    # Strip any accidental NULs (shouldn't occur) and keep under 4095 bytes before terminator
    s = s.replace('\x00', '')
    if len(s) > 4095:
        s = s[:4095]
    return s


def generate(seed: int) -> bytes:
    random.seed(seed)
    # Create several candidates and pick one to diversify output per seed
    variants = [_produce_variant() for _ in range(random.randint(1, 4))]
    s = random.choice(variants)

    # For coverage, optionally apply one more transformation
    if _maybe(0.4):
        # Focus on wildcard-to-regex conversion path occasionally
        s = _inject_wildcards(s)
    if _maybe(0.3):
        s = _sprinkle_regex_meta(s)
    if _maybe(0.2):
        s = _maybe_interval_prefix(s)

    s = _ensure_ascii_no_nul(s)

    # Encode as bytes (ASCII subset -> UTF-8-safe), add single trailing NUL
    b = s.encode('utf-8', errors='ignore')
    if len(b) >= 4096:
        b = b[:4095]
    return b + b'\x00'
